SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `vacancy_translation`;
CREATE TABLE `vacancy_translation` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `vacancy_id` int DEFAULT NULL,
  `amh` json DEFAULT NULL,
  `orm` json DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `vacancy_translation` (`id`, `vacancy_id`, `amh`, `orm`, `created_at`) VALUES
(6, 1, '{"type":"ሙሉ ጊዜ","title":"አስተዳደራዊ ረዳት","salary":"42000","skills":["document_management","time_management","communication_skills"],"category":"አስተዳደር","location":"የልደታ ክፍለ ከተማ ቢሮ","description":"በልደታ ክፍለ ከተማ የመንግሥት ቢሮ እንደ አስተዳደራዊ ረዳት ለየክፍሉ መሪዎች አጠቃላይ የአስተዳደር ድጋፍ ማቅረብ እና በሁሉም ክፍሎች ላይ ለስላሳ የቀን በቀን አሠራር ማረጋገጥ የሚያስጠብቅዎት ነው። ሚናዎ ደብዳቤን ማስተዳደር፣ ስብሰባዎችን እና ቀጠሮዎችን ማስተባበር፣ የተደራጁ የፋይል ስርዓቶችን መጠበቅ እና ለውስጥ እና ውጫዊ ባለድርሻዎች ዋና የመገናኛ ነጥብ ሆነው ማገልገልን ያካትታል። ከከፍተኛ ባለሥልጣናት ጋር በቅርበት በመስራት ሪፖርቶችን፣ ማቅረቢያዎችን እና ኦፊሴላዊ ሰነዶችን ይዘጋጃሉ፤ በተመሳሳይ ጊዜ ከመንግሥት ፕሮቶኮሎች እና ሂደቶች ጋር ማጣጣልን ያረጋግጣሉ። ይህ ክፍል �ተለይቶ የተደራጁ ክህሎቶችን፣ ዝርዝር ትኩረትን እና በፍጥነት በሚተዳደር የመንግሥት አካባቢ ውስጥ ብዙ ቅድሚያዎችን የማስተዳደር ችሎታን ይጠይቃል። ከቢሮ አቅርቦት፣ ለስብሰባዎች እና ክንውኖች ሎጂስቲክስን ማስተባበር እና የሚመለከታቸውን የመንግሥት መረጃዎች ሚስጥርነትን መጠበቅንም ያስጠብቃሉ።","qualifications":["ቢያንስ ዲፕሎማ በቢሮ አስተዳደር፣ የንግድ አስተዳደር ወይም ተዛማጅ ዘርፍ ከተረጋገጠ ተቋም በአስተዳደር ሂደቶች እና በቢሮ ቴክኖሎጂ የተረጋገጠ የትምህርት ሥራ ጋር","ቢያንስ ሁለት ዓመት የሚበልጥ የሂደት አስተዳደራዊ ድጋፍ በመንግሥት ቢሮዎች፣ ኩባንያ አካባቢዎች ወይም ትላልቅ ድርጅቶች ሚስጥራዊ መረጃን በሚስጥርነት ለማስተዳደር የተረጋገጠ ችሎታ ጋር","የማይክሮሶፍት ኦፊስ ስፉት (Word, Excel, PowerPoint, Outlook) እና የመንግሥት ሰነድ አስተዳደር ስርዓቶች ላይ የላቀ ችሎታ፤ ውስብስብ ሰነዶችን፣ ሰንጠረዦችን እና ማቅረቢያዎችን የመፍጠር ችሎታ","በአማርኛ እና በእንግሊዝኛ ልዩ የተጻፈ እና የቃል የመገናኛ ክህሎቶች፤ ሙያዊ ደብዳቤ የመፃፍ ችሎታ እና በተለያዩ ባለድርሻዎች ጋር ውጤታማ ማገናኘት ችሎታ","ብዙ ስራዎችን በማስቀድም፣ በጊዜ መወጣት እና በከፍተኛ ግፊት ሁኔታዎች ውስጥ ዝርዝር ትኩረትን በመጠበቅ የተረጋገጠ የተደራጁ እና የጊዜ አስተዳደር ችሎታዎች","ከባለሥልጣናት፣ ከሰራተኞች እና ከማህበረሰብ አባላት ጋር አወንታዊ የሥራ ግንኙነት የመገንባት ችሎታ፤ በተመሳሳይ ጊዜ ሙያዊ ወሰን የመጠበቅ ችሎታ","በኢትዮጵያ የመንግሥት መዋቅር ውስጥ የመንግሥት አስተዳደር ሂደቶች፣ የሰነድ ማቀናበር ፕሮቶኮሎች እና ኦፊሴላዊ የመገናኛ መንገዶች እውቀት","ሚስጥራዊ መረጃን የመጠበቅ ችሎታ እና በኦፊሴላዊ ጉዳዮች እና በውስጥ ባለ የመገናኛ ሂደቶች ውስጥ የድርሻ አሰጣጥ የመጠቀም ችሎታ"],"responsibilities":["የየክፍሉ መሪዎችን የቀን መቁጠሪያ፣ ቀጠሮዎች እና ስብሰባዎች ያስተዳድሩ እና ያስተባብሩ፤ ምርጥ የጊዜ ሰሌዳ እና የጊዜ አስተዳደርን በማረጋገጥ ብዙ ቅድሚያዎች ላይ፤ ግጭቶችን በማስቀደም እና መፍትሄዎችን በማቅረብ","ኦፊሴላዊ ሰነዶችን፣ ሪፖርቶችን፣ ማቅረቢያዎችን እና ደብዳቤዎችን በመንግሥት ደረጃዎች እና ፕሮቶኮሎች መሠረት ያዘጋጁ፣ ይገምግሙ እና ያቀርፉ፤ ትክክለኛነት፣ አጠቃላይነት እና ሙያዊ ማቅረቢያን በማረጋገጥ","የአስተዳደር ሰነዶች፣ ደብዳቤዎች እና መዝገቦች ለሚሆኑ አጠቃላይ የኤሌክትሮኒክ እና አካላዊ የፋይል ማስቀመጫ ስርዓቶችን ያስቀምጡ፤ ውጤታማ የማሰባሰብ ስርዓቶችን በመተግበር እና ከመንግሥት የመዝገብ አስቀምጢ ደንቦች ጋር ማጣጣልን በማረጋገጥ","የየክፍሉ መሪዎች እና ሌሎች የመንግሥት ቢሮዎች፣ የማህበረሰብ ድርጅቶች እና ህዝብ መካከል ዋና መስመር ሆነው ያገለግሉ፤ ጥያቄዎችን በሙያዊ ሁኔታ በማስተናገድ እና ተገቢውን ሠራተኞች ያመላክታሉ","ለስብሰባዎች፣ ስብሰባዎች እና ኦፊሴላዊ ክንውኖች ሎጂስቲክስን ያስተባብሩ፤ ይህም የቦታ ማዘጋጀቶችን፣ የመሣሪያ ማዋቀርን፣ የምግብ አቅርቦትን እና የስብሰባ ቁሳቁሶችን እና አጀንዳዎችን ዝግጅት ያካትታል","የቢሮ አቅርቦት አክሲዮን፣ የግዥ ሂደቶች እና የመሣሪያ ጥገና ያስተዳድሩ፤ ፍላጎቶችን በማስቀደም እና የመሠረታዊ ሀብቶች ቀጣይነት ያለው የመገኘትን እንዲያረጋግጡ","ኦፊሴላዊ ደብዳቤዎችን፣ ማስታወሻዎችን እና የመገናኛዎችን ያክል እና ይከታተሉ፤ በጊዜ ማከፋፈልን እና ሁሉንም ኦፊሴላዊ የመገናኛዎች ተገቢ ሰነድ አድርጎ ማቅረብን ያረጋግጡ","በገንዘብ መዝገቦችን በመከታተል፣ ፋክተሮችን በማከናወን እና ለየክፍሉ አሠራር የገንዘብ መዝገቦችን በመጠበቅ በጀት አዘጋጅታ እና ቁጥጥር ላይ ይረዱ"],"short_description":"የቀን በቀን የቢሮ አሠራርን አስተባብር እና ለየክፍሉ መሪዎች አጠቃላይ የአስተዳደር ድጋፍ ያቅርቡ። ደብዳቤ እና የጊዜ ሰሌዳ ያስተዳድሩ።"}', '{"type":"Yeroo Guutuu","title":"Gargaarsa Bulchinsaa","salary":"42000","skills":["document_management","time_management","communication_skills"],"category":"Bulchinsa","location":"Mana Hojii Lideta Sub-City","description":"Mana hojii mootummaa Lideta Sub-City keessatti akka Gargaarsa Bulchinsaa taateen, gargaarsa bulchinsaa guutuu hoggantoota qoqqoodaaf kennuufi hojii guyyataan walqabataa hunda qoqqooda keessatti mirkaneessuuf dhaabbata. Rooliin kee gaaffiiwwan bulchuu, walgahiiwwanfi beellamawwan walitti fiduu, sirna galmee qoqqoodamee turuufi tajaajiltoota dhuunfaa fi alaa gidduu bu''aa addaa taatee tajaajiluudha. Dhaabbileen ol aanaa wajjin walitti shira gahee, gabaa, fudhannoo fi dhaabbilee mootummaa qopheessuudhaan hojjettu; yeroo hundaa waliigala mootummaa fi tarsiimoota wajjin mirkaneessuudhaan. Kanaaf mijata qindoomina addaa, ibsa xiqqoo, fi dandeettii mijataa muraasa adda addaa loltuu bulchii mootummaa ariifaa ta''e keessatti bulchuun barbaachisa. Dabalataan, oomisha mana hojii, lojistikii walgahiifi taatee, fi icciti mootummaa icciti ta''e turuuf dhaabbata.","qualifications":["Diploomaa bu''aa ta''e Hojii Bulchinsaa, Hojii Daldalaa, ykn qoqqooda walitti dhufeenya mana hojii, fi dandeettii tarsiimoo bulchinsaa fi teknooloojii mana hojii irratti argame","Waggaa lama yoo ta''u ol hojii gargaarsa bulchinsaa deemaa ta''e mana hojii mootummaa, naannoo shirkii, ykn dhaabbilee guddaa keessatti, fi dandeettii mirkaneessaa icciti icciti ta''e bulchuuf","Dandeettii ol aanaa Suutii Makiirsoosoofiti Ofiisii (Word, Excel, PowerPoint, Outlook) fi sirna bulchuu dhaabbilee mootummaa, fi dandeettii dhaabbilee sirnaa, liqimssaa, fi fudhannoo uumuuf","Dandeettii barreeffamaafi dubbii ol aanaa Afaan Oromoo fi Ingiliffaa keessatti, fi dandeettii mirkaneessaa gaaffii hojii qopheessuufi tajaajiltoota adda addaa wajjin bilbilaa bu''aa qabu taasisuuf","Dandeettii qindoominaafi yeroo bulchii mirkaneessaa, fi dandeettii hojii muraasa qajeelchuuf, beellama guutuu, fi ibsa xiqqoo naannoo cimaa ta''e keessatti turuuf","Dandeettii walitti dhufeenya namaa cimaa, fi dandeettii dhaabbileen, hojjattoota, fi miseensa hawaasaa wajjin qajeelfama hojii ol''aanaa uumuuf, yeroo hundaa daangeffama hojii turuudhaan","Beekumsa tarsiimoo bulchinsaa mootummaa, waliigala dhaabbilee bulchuuf, fi karaa bilbilaa mootummaa qaama mootummaa Itoophiyaa keessatti","Dandeettii icciti icciti ta''e turuuf, fi dandeettii dhimma mootummaa fi tarsiimoo bilbilaa namaa gidduu keessatti murannoo fayyadamuuf"],"responsibilities":["Hoggantoota qoqqoodaaf kalaandarii, beellamawwan, fi walgahiiwwan bulchiifi walitti fidi, sa''ataa fi yeroon bulchii mijataa adda addaa walitti fidi, walgahiiwwan dhabamsiisuu fi furmaata dhiyeessuu","Dhaabbilee mootummaa, gabaa, fudhannoo, fi gaaffiiwwan sirnaafi waliigala mootummaa irratti hundaa''e qopheessi, xiinxali, fi suuta, dhugaa, waliigala, fi fudhannoo hojii dhaabbachuu mirkaneessi","Sirna galmee elektirootikii fi qaamaa dhaabbilee bulchinsaa, gaaffiiwwan, fi galmeewwanif qopheessi, sirna deebi''ii bu''aa qabu taasisi, fi waliigala galmee mootummaa wajjin mirkaneessi","Hoggantoota qoqqooda fi mana hojii mootummaa biroo, dhaabbilee hawaasaa, fi ummata gidduu bu''aa addaa ta''i, gaaffiiwwan akka hojii tiin deebisi, fi hojjattoota sirrii ta''an gorsisi","Lojistikii walgahii, hirmaannaa, fi taatee mootummaaaf walitti fidi, kan isaaniis qophii bakka, qophii meeshaa, kennumsa nyaataa, fi qophii meeshaa walgahii fi ajandaa","Akkawuntii oomisha mana hojii, tarsiimoo bitaa, fi eegumsa meeshaa bulchi, fedhiiwwan dhabamsiisuu, fi argina dhaabbataa qabeenya bu''aa ta''e mirkaneessuu","Gaaffiiwwan, yaad-rifeensa, fi bilbilaa mootummaa haalaafi galmeessi, yeroo hundaa qoqqooduu, fi dhaabbileen bilbilaa mootummaa hundaa galmee sirrii ta''e dhaabbachuu mirkaneessi","Bajetii qopheessuufi ilaaluu keessatti gargaari, baasiiwwan ilaaluu, faayilota qorichaa haalaafi, fi galmee maallaqa hojii qoqqoodaaf turu"],"short_description":"Hojii mana hojii guyyataan walitti fidi, gargaarsa bulchinsaa guutuu hoggantoota qoqqoodaaf kenni. Gaaffiiwwanfi sa''ataa bulchi."}', '2025-12-20 12:19:20'),
(7, 2, '{"type":"ሙሉ ጊዜ","title":"ጤና ባለሙያ","salary":"58000","skills":["epidemiology","community_engagement","data_analysis"],"category":"ጤና","location":"የልደታ ጤና ማዕከል","description":"ለልደታ ክፍለ ከተማ የመንግሥት ቢሮ እንደ ጤና ባለሙያ፣ አጠቃላይ የህዝብ ጤና ተቋሞች፣ የበሽታ ክትትል እና የጤና ትምህርት ፕሮግራሞች በኩል የማህበረሰብ ጤናን ለመጠበቅ እና ለማሻሻል ወሳኝ ሚና ትጫወታላችሁ። ኃላፊነቶቻችሁ የህዝብ ቁጥር የጤና አዝማሚያዎችን መከታተል፣ የበሽታ ስርጭቶችን መርምር፣ የመከላከያ የጤና እርምጃዎችን መተግበር እና ከጤና አገልግሎት ተቋማት እና የማህበረሰብ ድርጅቶች ጋር ማስተባበርን ያካትታሉ። በልደታ ማህበረሰብ ውስጥ ተራ የሆኑ የጤና ጉዳዮችን የሚያስተናግዱ የህዝብ ጤና ዘመቻዎችን ይዘጋጃሉ እና ያከናውናሉ፣ እነዚህም ከተላላፊ በሽታዎች፣ ከእናት እና የህጻናት ጤና፣ ከአመጋገብ እና ከተላላፊ ያልሆኑ በሽታዎች ጋር የተያያዙ ናቸው። ይህ ክፍል በልደታ ማህበረሰቦች ውስጥ የጤና እኩልነትን ለመለየት እና ተለይተው የተዘጋጁ እርምጃዎችን ለማስገባት በሜዳ ሥራ፣ በውሂብ ትንተና እና በማህበረሰብ ተሳትፎ የሚፈለግ ነው። በህዝብ ጤና ጉዳዮች ላይ የቴክኒክ አማካሪ በመሆን የሚያገለግሉ ሲሆን ለመንግሥት ባለሥልጣናት በማስረጃ ላይ የተመሰረቱ ምክሮችን ያቀርባሉ እና ከክልላዊ ጤና ባለስልጣናት ጋር በመስራት የክፍለ ከተማ ተቋሞችን ከብሔራዊ የጤና ቅድሚያዎች እና ከተጣራ የልማት ግቦች ጋር ያስባረራሉ።","qualifications":["የሳይንስ ባችለር ዲግሪ በህዝብ ጤና፣ በጤና ሳይንስ፣ በነርሲንግ ወይም ተዛማጅ ዘርፍ ከተረጋገጠ ዩኒቨርሲቲ በሕማም ምልክት፣ በባዮስታቲስቲክስ እና በማህበረሰብ ጤና የተረጋገጠ የትምህርት ሥራ ጋር","ቢያንስ ሶስት ዓመት በማህበረሰብ ጤና ፕሮግራም፣ በበሽታ ክትትል፣ በጤና ትምህርት ወይም በመንግሥት ወይም በኤንጂኦ ሁኔታዎች ውስጥ በተዛማጅ መስኮች ውስጥ ተግባራዊ የህዝብ ጤና ልምድ","የኢትዮጵያ ህዝብ ጤና ስርዓት፣ ብሔራዊ የጤና ፖሊሲዎች፣ የመጀመሪያ ደረጃ የጤና ማንከባከብ ስትራቴጂ እና ቅድሚያ የጤና ፕሮግራሞች አጠቃላይ እውቀት፤ በከተማ ሁኔታዎች ውስጥ አካባቢያዊ የጤና ተግዶላዎችን መረዳት","በሕማም ምልክት ምርመራ፣ በውሂብ ስብሰባ እና ትንተና፣ በስርጭት ምላሽ እና በጤና መረጃ ስርዓቶች አጠቃቀም ለክትትል እና ለግምገማ ዓላማዎች የተረጋገጠ ልምድ","በማህበረሰብ ተሳትፎ እና በጤና መገናኛ ላይ አስተማማኝ ክህሎቶች፤ ከባህል ግንኙነት ያላቸው የጤና መልዕክቶችን የመፍጠር ችሎታ እና ለተለያዩ ህዝቦች ውጤታማ የጤና ትምህርት ማቅረብ ችሎታ","በጤና ውሂብ ትርጉም መስጠት፣ አዝማሚያዎችን መለየት እና ለህዝብ ጤና እርምጃዎች በማስረጃ ላይ የተመሰረቱ ምክሮችን የመገንባት ችሎታ ጋር ጠንካራ የትንተና እና የችግር መፍታት ክህሎቶች","በውሂብ ትንተና ሶፍትዌር (EPI Info, SPSS, ወይም ተመሳሳይ) እና በማይክሮሶፍት ኦፊስ መተግበሪያዎች ላይ በውሂብ አስተዳደር፣ በትንተና እና በሪፖርት አዘጋጅታ ላይ ችሎታ","በብዙ የሙያ ቡድኖች ውስጥ በነጻ እና በአንድነት መስራት ችሎታ፣ ብዙ ፕሮጀክቶችን በአንድ ጊዜ ማስተዳደር ችሎታ እና ለሚቀያየሩ የህዝብ ጤና ቅድሚያዎች እና አደጋዎች የመስማማት ችሎታ"],"responsibilities":["በልደታ ክፍለ ከተማ ውስጥ ቅድሚያ ያላቸውን የጤና ጉዳዮች የሚያስተናግዱ አጠቃላይ የህዝብ ጤና ፕሮግራሞችን ይንደፉ፣ ያተግብሩ እና ይገምግሙ፤ እነዚህም የመከላከያ ዘመቻዎችን፣ የእናት ጤና ተቋሞችን፣ የበሽታ መከላከያ ፕሮግራሞችን እና የጤና ማሻሻያ እንቅስቃሴዎችን ያካትታሉ","በቤት ምርመራዎች፣ በጤና ተቋም ውሂብ ትንተና እና በሕማም ምልክት ምርመራዎች በኩል መደበኛ የማህበረሰብ ጤና ግምገማዎችን ያካሂዱ፤ የጤና አዝማሚያዎችን፣ የአደጋ ነገሮችን እና እየተዳደጉ ያሉ የህዝብ ጤና አደጋዎችን ለመለየት","የበሽታ ስርጭቶችን እና የህዝብ ጤና አደጋዎችን በመርምር እና በመቀበል፤ በሜዳ ምርመራዎችን በመካሄድ፣ የምላሽ ቡድኖችን በማስተባበር፣ የቁጥጥር እርምጃዎችን በመተግበር እና በመያዝ ላይ ያሉ ጥረቶችን በመከታተል","የባህል ግንኙነት ያላቸውን የጤና ትምህርት ቁሳቁሶችን፣ አውደ ማሰልጠኛዎችን እና የማህበረሰብ ማድረሻ ፕሮግራሞችን ይዘጋጁ እና ያቅርቡ፤ ይህም ትምህርት ቤቶችን፣ ሃይማኖታዊ ተቋማትን፣ የሥራ ቦታዎችን እና የማህበረሰብ ድርጅቶችን ያገባል","በክፍለ ከተማው ውስጥ በህዝብ እና በግል ጤና ተቋማት ላይ የጤና አገልግሎት አቅርቦትን ይከታተሉ እና ይገምግሙ፤ የእርካታ ጥራትን፣ የአገልግሎት ተገኝነትን እና ከብሔራዊ የጤና ደረጃዎች እና ፕሮቶኮሎች ጋር ማጣጣልን በመገምገም","የህዝብ ጤና ውሂብን በመደበኛ የሪፖርት ስርዓቶች በመጠቀም ይሰብስቡ፣ ይተነትኑ እና ይለጥፉ፤ ለመንግሥት ባለሥልጣናት እና ባለድርሻዎች አጠቃላይ የሕማም ምልክት ሪፖርቶችን፣ የሁኔታ ትንተናዎችን እና የፕሮግራም ግምገማዎችን ያዘጋጁ","ከክልላዊ ጤና ቢሮዎች፣ ከኤንጂኦዎች፣ ከማህበረሰብ የተመሰረቱ ድርጅቶች እና ከጤና አገልግሎት አቅራቢዎች ጋር ያስተባብሩ፤ የህዝብ ጤና ጥረቶችን ለማስተካከል፣ ሀብቶችን ለማጎልበት እና የተቀናጀ የጤና እርምጃዎችን ለማስገባት","በህዝብ ጤና ልምምዶች፣ በውሂብ ስብሰባ ዘዴዎች እና በጤና ትምህርት ቴክኒኮች ላይ ለማህበረሰብ ጤና ሠራተኞች፣ ለጤና ማስፋፊያ ሠራተኞች እና ለበጎ ፈቃደኞች ቴክኒካዊ መመሪያ እና አቅም ግንባታ ያቅርቡ"],"short_description":"የማህበረሰብ ጤና ተቋሞችን እና የበሽታ መከላከያ ፕሮግራሞችን ያስተዳድሩ። የሕማም ምልክት ክትትል ያካሂዱ እና የጤና ትምህርት ዘመቻዎችን ያስተባብሩ።"}', '{"type":"Yeroo Guutuu","title":"Hojjeta Fayyaa Ummataa","salary":"58000","skills":["epidemiology","community_engagement","data_analysis"],"category":"Fayyaa","location":"Giddugaleessa Fayyaa Lideta","description":"Lideta Sub-City mana hojii mootummaa keessatti akka Hojjeta Fayyaa Ummataa taateen, fayyaa hawaasaa eeguufi fooyya''isuuf, surveillance dhukkubaa, fi pirograamoonni barsiisa fayyaa wajjin dhimma murteessaa taphatta. Dhimmiwwan kee dhangaa''aa fayyaa ummataa ilaaluu, dhukkuba baasuun qoruu, tarkaanfii fayyaa dhorguu raawwachiisuufi, mana fayyaafi dhaabbilee hawaasaa wajjin walitti shira godhuu dha. Pirograamoonni fayyaa ummataa fi kampaaniiwwan kanneen dhukkuboota mul''atan Lideta hawaasa keessatti, kanneen dhukkuboota dhiigaa, fayyaa haadhaafi daa''immaa, nyaataafi dhukkuboota dhiigaa hin qabne kanneen dabalatan qopheessuufi raawwatudha. Kun tajaajila naannoo, qorannoo daataa, fi hawaasa haala keessatti hirmaachuufi fedhiin fayyaa walsimsiisuufi tarkaanfilee kanneen dhukkuboota adda addaa itti fufuuf dha. Akka ammayyaatti, dhimma fayyaa ummataa irratti gorsa teknikaalaa kennita, dhaabbileen mootummaaaf yaada mirkaneessaa kennita, fi waliigala fayyaa naannoo wajjin walitti shira godhaa kaayyoo sub-city qoqqooda waliigala fayyaa fi kaayyoo guddisa dhaabbataa wajjin walitti hidhuu dha.","qualifications":["Digirii Saayinsii Baachilerii fayyaa ummataa, Saayinsii Fayyaa, Naarsii, ykn qoqqooda walitti dhufeenya irraa kan ta''e yunivarsiitii amanamaa ta''e, kanneen epidemiology, biostatistics, fi fayyaa hawaasaa wajjin qophaa''e","Waggaa sadi yoo ta''u ol tajaajila fayyaa ummataa naannoo, pirograamii fayyaa hawaasaa, surveillance dhukkuba, barsiisa fayyaa, ykn qoqqooda walitti dhufeenya mootummaa ykn NGO keessatti","Beekumsa guutuu sirna fayyaa ummataa Itoophiyaa, sirna fayyaa waliigalaa, strateejii tajaajila fayyaa jalqabaa, fi pirograamoonni fayyaa murteessaa fi beekumsa dhibee fayyaa naannoo naannoo magaalaa keessatti","Beekumsa mirkaneessaa qorannoo epidemiolojikii, qabsiifannaa daataafi qorannoo, deebii ba''aa, fi fayyadama sirna iccitii fayyaa eeguufi qorannoo","Dandeettii gammachiisaa hawaasaa fi bilbilaa fayyaa ol''aanaa, fi dandeettii oggaa fayyaa aadaa uumuufi barsiisa fayyaa bu''aa qabu haala adda addaa irratti kennuuf","Dandeettii qorannoofi furmaata dhibee cimaa, fi dandeettii daataa fayyaa hiikuu, dhangaa''aa ilaaluu, fi yaada mirkaneessaa tarkaanfii fayyaa ummataaf qopheessuuf","Dandeettii ol''aanaa sooftiweerii qorannoo daataa (EPI Info, SPSS, ykn fakkaataa) fi Microsoft Office fayyadamuuf qabsiifannaa daataa, qorannoo, fi qophii gabaa","Dandeettii hojii dhuunfaa fi walitti shira garee adda addaa keessatti, piroojektii muraasa yeroo tokko bulchuufi, fi dandeettii jijjiirama murteessaa fayyaa ummataa fi yeroo barbaachisaa wajjin walqabataa ta''uuf"],"responsibilities":["Pirograamoonni fayyaa ummataa guutuu kanneen dhimma fayyaa murteessaa Lideta Sub-City keessatti, kanneen kampaanii tarkaanfii, kaayyoo fayyaa haadhaa, pirograamoonni dhukkuba dhorguu, fi gochaalee fayyaa daddabsiisuu dabalatan qopheessi, raawwachiisi, fi qorannoo","Madaala fayyaa hawaasaa yeroo yeroo ta''e kanneen gaaffii manaa, qorannoo daataa mana fayyaa, fi qorannoo epidemiolojikii wajjin raawwachiisi akka dhangaa''aa fayyaa, dhibee, fi dhukkuba fayyaa ummataa itti aanu mul''atu ilaaluuf","Dhukkuba baasuun fi deebii dhukkuba fayyaa ummataa yeroo barbaachisaa ta''e ilaaluufi deebisuu, kanneen qorannoo naannoo, garee deebii walitti fiduu, tarkaanfii tajaajiluufi, fi tajaajila dhukkuba itti fufuuf eeguu wajjin raawwachiisi","Meeshaa barsiisa fayyaa kanneen aadaa, waaksiiwwan, fi pirograamoonni hawaasaa deemu kanneen barumsa, dhaabbilee amantaa, bakka hojii, fi dhaabbilee hawaasaa kanneen hordofu qopheessiifi kenni","Tajaajila fayyaa mana fayyaa ummataafi kan dhuunfaa sub-city keessatti eeguufi qorannoo, sirna fayyaa waliigalummaa, argina tajaajilaa, fi waliigala waliigala fayyaa fi waliigala waliigalaa wajjin walqabataa ilaaluu","Daataa fayyaa ummataa sirna galmaa''aa fayyadamuun qabsiifi, qorannoo, fi galmee, gabaa guutuu epidemiolojikii, qorannoo haala, fi qorannoo pirograamii dhaabbileen mootummaa fi tajaajiltootaaf qopheessi","Waliigala fayyaa naannoo, NGO, dhaabbilee hawaasa irraa kanneen, fi kennaawwan fayyaa wajjin walitti shira godhaa kaayyoo fayyaa ummataa, qabeenya fayyadamuufi, fi tarkaanfii fayyaa waliigalaa raawwachiisuuf","Gorsa teknikaalaa fi qabeenya ijaarsaa hojjattoota fayyaa hawaasaa, daddabartoota fayyaa, fi fedhiiftoota dhimma tajaajila fayyaa ummataa, daataa qabsiifachuu, fi mala barsiisa fayyaa irratti kenni"],"short_description":"Kaayyoo fayyaa hawaasaa fi pirograamoonni dhukkuba dhorguu qajeelchi. Surveillance epidemiologikii gaggeessi, kampaanii barsiisa fayyaa walitti fidi."}', '2025-12-20 12:38:42'),
(8, 3, '{"type":"ሙሉ ጊዜ","title":"የአካባቢ ተቆጣጣሪ","salary":"52000","skills":["regulatory_compliance","environmental_monitoring","technical_reporting"],"category":"አካባቢ","location":"ልደታ ክፍለ ከተማ","description":"ለልደታ ክፍለ ከተማ የመንግሥት ቢሮ እንደ የአካባቢ ተቆጣጣሪ፣ የአካባቢ ደንቦችን ማስከበር፣ የንግድ እና የኢንዱስትሪ ተቋማትን አጠቃላይ ክትትሎችን ማካሄድ እና ከብሔራዊ እና ከከተማ የአካባቢ ደረጃዎች ጋር ማጣጣልን ማረጋገጥ የሚያስጠብቅዎት ነው። ሚናዎ የመርከቦች ምንጮች፣ የነፍሳት አስተዳደር ልምዶች እና የአካባቢ ተጽዕኖ የተለያዩ እንቅስቃሴዎችን በክፍለ ከተማው ውስጥ የሚረጋገጥ ስርዓታዊ ግምገማን ያካትታል። የአየር ጥራት ደረጃዎች፣ የውሃ ብክለት ቁጥጥሮች፣ የነፍሳት ማስወገጃ ደንቦች እና የድምፅ ብክለት ገደቦችን ለመገምገም የማምረቻ ተቋማትን፣ የአገልግሎት መስሪያ ቤቶችን፣ የግንባታ ቦታዎችን እና የመኖሪያ ልማቶችን ዝርዝር ክትትሎችን ያካሂዳሉ። ይህ ክፍል የአካባቢ ሳይንስ፣ የአስተዳደር መዋቅሮች እና የክትትል ዘዴዎች ቴክኒካዊ እውቀትን ይጠይቃል። የነዋሪዎችን የአካባቢ ቅሬታዎች ያሰስታሉ፣ የቁጠጣ እርምጃዎችን ይመክራሉ እና በሕገወጥ ላይ በመከታተል ተገቢው የማስተካከያ ሥራ እንዲከናወን ያረጋግጣሉ። በተጨማሪም ለአካባቢ ፖሊሲ እድገት እና ለህዝባዊ ትምህርት ተቋሞች ያበርክታሉ ይህም በልደታ ማህበረሰብ ውስጥ ዘላቂ ልምዶችን ለማስተዋወቅ የተነደፈ ነው።","qualifications":["የአካባቢ ሳይንስ፣ የአካባቢ ምህንድስና፣ ኬሚስትሪ ወይም ተዛማጅ ዘርፍ የባችለር ዲግሪ በአካባቢ ደንቦች፣ በብክለት ቁጥጥር እና በአካባቢ ክትትል የተረጋገጠ የትምህርት ሥራ ጋር","ቢያንስ ሶስት ዓመት የሙያ ልምድ በአካባቢ ክትትል፣ በማጣጣል ክትትል፣ በብክለት ቁጥጥር ወይም በመንግሥት ወይም በኢንዱስትሪ ሁኔታዎች ውስጥ በአስተዳደር ማስከበር","በፌዴራል፣ ክልላዊ እና ከተማ ደረጃዎች ላይ የኢትዮጵያ የአካባቢ ሕጎች፣ ደንቦች፣ ደረጃዎች እና የፈቃድ መስፈርቶች ጥልቅ እውቀት፤ ከማስከበር ሂደቶች ጋር መረዳት","በአካባቢ ክትትል ቴክኒኮች፣ በናሙና ማውጣት ፕሮቶኮሎች፣ በመስክ የመለኪያ መሣሪያ እና በላቦራቶሪ ትንተና ዘዴዎች ላይ ቴክኒካዊ ችሎታ፤ ለአየር፣ ለውሃ እና ለአፈር ጥራት መለኪያዎች","በቴክኒካዊ ውሂብ ትርጉም መስጠት፣ በአስተዳደር ሕገወጥነቶችን መለየት እና በአደጋ ግምገማ ላይ በመመስረት ተገቢ የማስከበር ምላሾችን የመገንባት ችሎታ ጋር ጠንካራ የምርመራ እና የትንተና ክህሎቶች","ግልጽ፣ አጠቃላይ እና በሕግ ሊጠበቅ የሚችል የክትትል ሪፖርቶችን፣ የሕገወጥ ማስታወቂያዎችን እና የማጣጣል ሰነዶችን የመጻፍ ችሎታ ጋር አስተማማኝ የሪፖርት ጻፊያ እና የሰነድ ክህሎቶች","በተለያዩ ተጋሪዎች ላይ ውስብስብ የአካባቢ ደንቦችን ለማብራራት፣ የማጣጣል ስምምነቶችን ለማሸነፍ እና በግጭት ሁኔታዎች ውስጥ በሙያዊ ሁኔታ ለማስተዳደር ችሎታ ጋር ውጤታማ የመገናኛ እና በውስጥ ባለ ሰዎች ክህሎቶች","በተለያዩ አካባቢዎች ውስጥ በመስክ ክትትሎችን ለማካሄድ አካላዊ ችሎታ፤ ከኢንዱስትሪ ተቋማት፣ ከግንባታ ቦታዎች እና ከሊቅ የአደጋ ሁኔታዎች ጋር ተገቢ የደህንነት እርጥበት ጋር"],"responsibilities":["የኢንዱስትሪ ተቋማትን፣ የንግድ መስሪያ ቤቶችን፣ የግንባታ ቦታዎችን እና የአገልግሎት አቅራቢዎችን በተፈረመ እና በድንገተኛ ክትትሎች ያካሂዱ፤ ከአካባቢ ደንቦች፣ ፈቃዶች እና ደረጃዎች ጋር ማጣጣልን ይገምግሙ","ከነዋሪዎች የሚመጡ የአካባቢ ቅሬታዎችን በብክለት፣ በማያስቻል የነፍሳት ማስወገጃ፣ በድምፅ ሕገወጥነት እና በሌሎች የአካባቢ ግዴታዎች ላይ ያሰስቱ፤ ውጤቶችን በማስቀመጥ እና ተገቢ የማስከበር እርምጃዎችን በማመከር","ከአካባቢ ናሙናዎችን (አየር፣ ውሃ፣ አፈር) በመደበኛ ፕሮቶኮሎች በመከተል ይሰብስቡ፤ የላቦራቶሪ ትንተናን ያስተባብሩ፣ ውጤቶችን ይተረጉሙ እና በአካባቢ ጥራት እና በብክለት ደረጃዎች ላይ ቴክኒካዊ ሪፖርቶችን ያዘጋጁ","ለአካባቢ ደረጃዎች ለማይደርሱ ተቋማት የሕገወጥ ማስታወቂያዎችን፣ የማጣጣል ትዕዛዞችን እና የአስተዳደር ወንጀሎችን ያስተላልፉ፤ የማስከበር እርምጃዎች እና የተከታተል እንቅስቃሴዎችን ዝርዝር መዝገቦችን ያቆዩ","ለታቀዱ ልማቶች የአካባቢ ተጽዕኖ ግምገማዎችን እና የአስተዳደር ዕቅዶችን ይገምግሙ፤ ቴክኒካዊ ምክሮችን ይስጡ እና የቁጠጣ እርምጃዎችን አተገባበርን ይከታተሉ","የተቋማትን አጠቃላይ የአካባቢ አፈፃፀም ለመገምገም የአካባቢ ኦዲቶችን ያካሂዱ፤ ለማሻሻል እድሎችን ይለዩ እና ለቁጠጣ እርምጃዎች የማጣጣል ሰሌዳዎችን ይዘጋጁ","በማግኘት፣ በመታየት፣ በፎቶግራፍ፣ በመለኪያ እና በማጣጣል እና በአካባቢ ጥበቃ ምክሮች ላይ ያሉ ግምገማ ሪፖርቶችን ያዘጋጁ","በንግድ ባለቤቶች፣ በተቋም አስተዳዳሪዎች እና በማህበረሰብ አባላት ላይ የአካባቢ ደንቦች፣ የብክለት መከላከያ ቴክኒኮች እና ዘላቂ ልምዶችን በተመለከተ ቴክኒካዊ መመሪያ እና ትምህርት ይስጡ"],"short_description":"የአካባቢ ደንቦችን አስከብሩ እና የተቋም ክትትሎችን ያካሂዱ። ከአየር ጥራት እና ከነፍሳት አስተዳደር ደረጃዎች ጋር ማጣጣልን ያረጋግጡ።"}', '{"type":"Yeroo Guutuu","title":"Ilaala Naannoo","salary":"52000","category":"Naannoo","location":"Lideta Sub-City","description":"Mana hojii mootummaa Lideta Sub-City keessatti akka Ilaala Naannoo taateen, safuu naannoo dhaabuuf, ilaala dhaabbataa guutuu shirkii fi indaastirii gaggeessuufi, waliigala naannoo fi naannoo magaalaa wajhin walqabataa mirkaneessuuf dhaabbata. Rooliin kee qorannoo sirnaa bu''aa baasa, tajaajila bulchiinsa saaphanaa, fi bu''aa naannoo gochaalee adda addaa sub-city keessatti qorannoo dha. Ilaala xiqqaa ta''e indaastirii oomishaa, bakka tajaajilaa, bakka ijaarsaa, fi hundeeffama jireenyaa walqabataa qulqullina qilleensa, tajaajilaa bishaan qubeessuu, safuu saaphanaa, fi daangeffama qubeessuu dhagaa ilaaluu dha. Kun beekumsa teknikaalaa saayinsii naannoo, qaama safuu, fi mala ilaalaa barbaachisa. Iciti jireenyaa naannoo ilaaluu, tarkaanfii sirrii yaaduufi, fi dhiibbaa sirrii mirkaneessuuf ba''aa hawaasaa naannoo ilaaluu dha. Dabalataan, qopheessaa naannoo naannoo fi kaayyoo barsiisa ummataa hawaasa Lideta keessatti tajaajila dhaabbataa daddabsiisuuf kan qophaa''e taatee dha.","qualifications":["Digirii Baachilerii Saayinsii Naannoo, Injinarii Naannoo, Kemistirii, ykn qoqqooda walitti dhufeenya irraa qophaa''e mala safuu naannoo, tajaajilaa qubeessuu, fi ilaalaa naannoo","Waggaa sadi yoo ta''u ol tajaajila hojii ilaalaa naannoo, eeguu walqabataa, tajaajilaa qubeessuu, ykn dhaabu safuu mootummaa ykn indaastirii keessatti","Beekumsa gadi fagoo seera naannoo Itoophiyaa, safuu, waliigala, fi hayyama murteessaa adda addaa fi federaalaa, naannoo, fi naannoo magaalaa, fi hubannaa tarsiimoo dhaabuuf","Dandeettii teknikaalaa mala ilaalaa naannoo, waliigalaa faayila qabsiifachuu, meeshaa safara naannoo, fi mala qorannoo laaboratoorii qulqullina qilleensa, bishaan, fi dhoqqee","Dandeettii qorannoofi qorannoo cimaa, fi dandeettii daataa teknikaalaa hiikuu, dhiibbaa safuu ilaaluu, fi deebii dhaabuuf sirrii ta''e bu''aa madaala dhibee irratti hundaa''e qopheessuuf","Dandeettii barreeffama gabaa ol''aanaa fi galmeeessuu, fi dandeettii ifaa, guutuu, fi seeraan eegamaa ta''e gabaa ilaalaa, beeksisa dhiibbaa, fi galmee walqabataa qopheessuuf","Dandeettii bilbilaa fi dandeettii nama gidduu bu''aa qabu, fi dandeettii safuu naannoo sirrii ta''e haala adda addaa irratti ibsuu, walii galtee walqabataa mariisuu, fi haala dorgomaa akka hojii tiin bulchuuf","Dandeettii qaamaa ilaalaa naannoo haala adda addaa keessatti raawwachiisuuf, kanneen dhaabbataa indaastirii, bakka ijaarsaa, fi hawwa dhibee danda''aa ta''e, fi daandiiwwan nageenya sirrii wajhin"],"responsibilities":["Ilaala yeroo ykn ba''a ta''e indaastirii, bakka daldalaa, bakka ijaarsaa, fi kennawwan tajaajilaa safuu naannoo, hayyama, fi waliigalaa wajhin walqabataa ilaaluuf","Iciti jireenyaa naannoo jiraattoota irraa qorannoo, dhiibbaa saaphanaa sirrii ta''e hin qabne, dhiibbaa dhagaa, fi dhimma naannoo biroo ilaaluu, argina galmeessuu, fi tarkaanfii dhaabuuf sirrii yaaduu","Faayila naannoo (qilleensa, bishaan, dhoqqee) waliigalaa hordofuun qabsiifadhu, qorannoo laaboratoorii walitti fiduu, bu''aa hiikuu, fi gabaa teknikaalaa qulqullina naannoo fi sadarkaa qubeessuu irratti qopheessu","Beeksa dhiibbaa, ajaja walqabataa, fi kaffaltii bulchinsaa dhaabbatoonni waliigala naannoo hin milkaa''in irratti kennuu, galmee sirrii ta''e tarkaanfii dhaabuufi hordoffii hawaasaa turu","Qorannoo bu''aa naannoo fi qophii bulchinsaa hundeeffama itti aanu ilaaluu, yaada teknikaalaa dhiyeessuu, fi raawwachiinsa tarkaanfii hir''isuu ilaaluu","Auditii naannoo dhaabbataa irratti raawwachiisuun dandeettii naannoo guutuu ilaaluu, carraa fooyya''insa ilaaluu, fi sa''ataa sirrii tarkaanfii sirrii ta''e qopheessuu","Gabaa ilaalaa guutuu kanneen argina, ilaalcha, suuraa, safara, fi yaada walqabataa safuu naannoo fi eeguu naannoo irratti qopheessu","Gorsa teknikaalaafi barsiisa abbaa daldalaa, bulchaa dhaabbataa, fi miseensa hawaasaa safuu naannoo, mala qubeessuu dhorguu, fi tajaajila dhaabbataa irratti kennu"],"short_description":"Safuu naannoo dhaabu, ilaala dhaabbataa gaggeessi. Walqabataa qulqullina qilleensaafi bulchiinsa saaphanaa ilaali."}', '2025-12-20 12:38:42'),
